27: typedef struct TTF_SurfaceTextEngineGlyphData
28: {
29:     int refcount;
30:     SDL_Color color;
31:     SDL_Surface *surface;
32:     TTF_ImageType image_type;
33: } TTF_SurfaceTextEngineGlyphData;
34: 
35: typedef struct TTF_SurfaceTextEngineTextData
36: {
37:     SDL_FColor fcolor;
38:     SDL_Color color;
39:     TTF_DrawOperation *ops;
40:     int num_ops;
41: } TTF_SurfaceTextEngineTextData;
42: 
43: typedef struct TTF_SurfaceTextEngineFontData
44: {
45:     TTF_Font *font;
46:     Uint32 generation;
47:     SDL_HashTable *glyphs;
48: } TTF_SurfaceTextEngineFontData;
49: 
50: typedef struct TTF_SurfaceTextEngineData
51: {
52:     SDL_HashTable *fonts;
53: } TTF_SurfaceTextEngineData;
54: 
55: 
56: static void DestroyGlyphData(TTF_SurfaceTextEngineGlyphData *data)
57: {
58:     if (!data) {
59:         return;
60:     }
61: 
62:     --data->refcount;
63:     if (data->refcount == 0) {
64:         if (data->surface) {
65:             SDL_DestroySurface(data->surface);
66:         }
67:         SDL_free(data);
68:     }
69: }
70: 
71: static TTF_SurfaceTextEngineGlyphData *CreateGlyphData(SDL_Surface *surface, TTF_ImageType image_type)
72: {
73:     TTF_SurfaceTextEngineGlyphData *data = (TTF_SurfaceTextEngineGlyphData *)SDL_malloc(sizeof(*data));
74:     if (data) {
75:         data->refcount = 1;
76:         data->color.r = 0xFF;
77:         data->color.g = 0xFF;
78:         data->color.b = 0xFF;
79:         data->color.a = 0xFF;
80:         data->surface = surface;
81:         data->image_type = image_type;
82:     }
83:     return data;
84: }
85: 
86: static TTF_SurfaceTextEngineGlyphData *GetGlyphData(TTF_SurfaceTextEngineFontData *fontdata, TTF_Font *glyph_font, Uint32 glyph_index)
87: {
88:     TTF_SurfaceTextEngineGlyphData *data;
89: 
90:     if (!SDL_FindInGlyphHashTable(fontdata->glyphs, glyph_font, glyph_index, (const void **)&data)) {
91:         TTF_ImageType image_type = TTF_IMAGE_INVALID;
92:         SDL_Surface *surface = TTF_GetGlyphImageForIndex(glyph_font, glyph_index, &image_type);
93:         if (!surface) {
94:             return NULL;
95:         }
96: 
97:         data = CreateGlyphData(surface, image_type);
98:         if (!data) {
99:             return NULL;
100:         }
101: 
102:         if (!SDL_InsertIntoGlyphHashTable(fontdata->glyphs, glyph_font, glyph_index, data)) {
103:             DestroyGlyphData(data);
104:             return NULL;
105:         }
106:     }
107:     return data;
108: }
109: 
110: static void DestroyTextData(TTF_SurfaceTextEngineTextData *data)
111: {
112:     if (!data) {
113:         return;
114:     }
115: 
116:     if (data->ops) {
117:         for (int i = 0; i < data->num_ops; ++i) {
118:             const TTF_DrawOperation *op = &data->ops[i];
119:             if (op->cmd == TTF_DRAW_COMMAND_COPY) {
120:                 TTF_SurfaceTextEngineGlyphData *glyph = (TTF_SurfaceTextEngineGlyphData *)op->copy.reserved;
121:                 DestroyGlyphData(glyph);
122:             }
123:         }
124:         SDL_free(data->ops);
125:     }
126:     SDL_free(data);
127: }
128: 
129: static TTF_SurfaceTextEngineTextData *CreateTextData(TTF_SurfaceTextEngineFontData *fontdata, const TTF_DrawOperation *ops, int num_ops)
130: {
131:     TTF_SurfaceTextEngineTextData *data = (TTF_SurfaceTextEngineTextData *)SDL_calloc(1, sizeof(*data));
132:     if (!data) {
133:         return NULL;
134:     }
135: 
136:     data->ops = (TTF_DrawOperation *)SDL_malloc(num_ops * sizeof(*data->ops));
137:     if (!data->ops) {
138:         DestroyTextData(data);
139:         return NULL;
140:     }
141:     SDL_memcpy(data->ops, ops, num_ops * sizeof(*data->ops));
142:     data->num_ops = num_ops;
143: 
144:     for (int i = 0; i < data->num_ops; ++i) {
145:         TTF_DrawOperation *op = &data->ops[i];
146:         if (op->cmd == TTF_DRAW_COMMAND_COPY) {
147:             TTF_SurfaceTextEngineGlyphData *glyph = GetGlyphData(fontdata, op->copy.glyph_font, op->copy.glyph_index);
148:             if (!glyph) {
149:                 DestroyTextData(data);
150:                 return NULL;
151:             }
152:             ++glyph->refcount;
153:             op->copy.reserved = glyph;
154:         }
155:     }
156:     return data;
157: }
158: 
159: static void DestroyFontData(TTF_SurfaceTextEngineFontData *data)
160: {
161:     if (!data) {
162:         return;
163:     }
164: 
165:     if (data->glyphs) {
166:         SDL_DestroyGlyphHashTable(data->glyphs);
167:     }
168:     SDL_free(data);
