97: static int SDLCALL SortMissing(void *userdata, const void *a, const void *b)
98: {
99:     const TTF_DrawOperation *ops = (const TTF_DrawOperation *)userdata;
100:     const stbrp_rect *A = (const stbrp_rect *)a;
101:     const stbrp_rect *B = (const stbrp_rect *)b;
102: 
103:     // Sort missing first
104:     if (!ops[A->id].copy.reserved) {
105:         if (ops[B->id].copy.reserved) {
106:             return -1;
107:         }
108:     }
109:     if (!ops[B->id].copy.reserved) {
110:         if (ops[A->id].copy.reserved) {
111:             return 1;
112:         }
113:     }
114: 
115:     // Sort largest first
116:     if (A->w != B->w) {
117:         if (A->w > B->w) {
118:             return -1;
119:         } else {
120:             return 1;
121:         }
122:     }
123:     if (A->h != B->h) {
124:         if (A->h > B->h) {
125:             return -1;
126:         } else {
127:             return 1;
128:         }
129:     }
130: 
131:     // It doesn't matter, sort by ID
132:     if (A->id < B->id) {
133:         return -1;
134:     } else {
135:         return 1;
136:     }
137: }
138: 
139: static int SDLCALL SortOperations(const void *a, const void *b)
140: {
141:     const TTF_DrawOperation *A = (const TTF_DrawOperation *)a;
142:     const TTF_DrawOperation *B = (const TTF_DrawOperation *)b;
143: 
144:     if (A->cmd == TTF_DRAW_COMMAND_COPY &&
145:         B->cmd == TTF_DRAW_COMMAND_COPY) {
146:         AtlasGlyph *glyphA = (AtlasGlyph *)A->copy.reserved;
147:         AtlasGlyph *glyphB = (AtlasGlyph *)B->copy.reserved;
148:         if (glyphA->atlas != glyphB->atlas) {
149:             // It's not important how we sort this, just that it's consistent
150:             return (glyphA->atlas < glyphB->atlas) ? -1 : 1;
151:         }
152: 
153:         // We could sort by texture coordinate or whatever, if we cared.
154:         return 0;
155:     }
156: 
157:     if (A->cmd == TTF_DRAW_COMMAND_COPY) {
158:         return -1;
159:     }
160:     if (B->cmd == TTF_DRAW_COMMAND_COPY) {
161:         return 1;
162:     }
163:     return 0;
164: }
