175: static void DestroyAtlas(AtlasTexture *atlas)
176: {
177:     if (!atlas) {
178:         return;
179:     }
180: 
181:     AtlasGlyph *next;
182:     for (AtlasGlyph *glyph = atlas->free_glyphs; glyph; glyph = next) {
183:         next = glyph->next;
184:         DestroyGlyph(glyph);
185:     }
186: 
187:     SDL_DestroyTexture(atlas->texture);
188:     SDL_free(atlas->packing_nodes);
189:     SDL_free(atlas);
190: }
