192: static AtlasTexture *CreateAtlas(SDL_Renderer *renderer, int atlas_texture_size)
193: {
194:     AtlasTexture *atlas = (AtlasTexture *)SDL_calloc(1, sizeof(*atlas));
195:     if (!atlas) {
196:         return NULL;
197:     }
198: 
199:     atlas->texture = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STREAMING, atlas_texture_size, atlas_texture_size);
200:     if (!atlas->texture) {
201:         DestroyAtlas(atlas);
202:         return NULL;
203:     }
204:     SDL_SetTextureScaleMode(atlas->texture, SDL_SCALEMODE_NEAREST);
205: 
206:     int num_nodes = atlas_texture_size / 4;
207:     atlas->packing_nodes = (stbrp_node *)SDL_calloc(num_nodes, sizeof(*atlas->packing_nodes));
208:     if (!atlas->packing_nodes) {
209:         DestroyAtlas(atlas);
210:         return NULL;
211:     }
212:     stbrp_init_target(&atlas->packer, atlas_texture_size, atlas_texture_size, atlas->packing_nodes, num_nodes);
213:     stbrp_setup_heuristic(&atlas->packer, STBRP_HEURISTIC_Skyline_default);
214: 
215:     return atlas;
