218: static void ReleaseGlyph(AtlasGlyph *glyph)
219: {
220:     if (!glyph) {
221:         return;
222:     }
223: 
224:     --glyph->refcount;
225:     if (glyph->refcount == 0) {
226:         if (glyph->atlas) {
227:             // Insert into free list sorted smallest first
228:             AtlasGlyph *entry, *prev = NULL;
229:             int size = (glyph->rect.w * glyph->rect.h);
230:             for (entry = glyph->atlas->free_glyphs; entry; entry = entry->next) {
231:                 if (size <= (entry->rect.w * entry->rect.h)) {
232:                     break;
233:                 }
234: 
235:                 prev = entry;
236:             }
237: 
238:             if (prev) {
239:                 prev->next = glyph;
240:             } else {
241:                 glyph->atlas->free_glyphs = glyph;
242:             }
243:             glyph->next = entry;
244:         } else {
245:             DestroyGlyph(glyph);
246:         }
247:     }
248: }
