250: static AtlasGlyph *CreateGlyph(AtlasTexture *atlas, int atlas_texture_size, const stbrp_rect *area)
251: {
252:     AtlasGlyph *glyph = (AtlasGlyph *)SDL_calloc(1, sizeof(*glyph));
253:     if (!glyph) {
254:         return NULL;
255:     }
256: 
257:     glyph->refcount = 1;
258:     glyph->atlas = atlas;
259:     glyph->rect.x = area->x;
260:     glyph->rect.y = area->y;
261:     glyph->rect.w = area->w;
262:     glyph->rect.h = area->h;
263: 
264:     const float minu = (float)area->x / atlas_texture_size;
265:     const float minv = (float)area->y / atlas_texture_size;
266:     const float maxu = (float)(area->x + area->w) / atlas_texture_size;
267:     const float maxv = (float)(area->y + area->h) / atlas_texture_size;
268:     glyph->texcoords[0] = minu;
269:     glyph->texcoords[1] = minv;
270:     glyph->texcoords[2] = maxu;
271:     glyph->texcoords[3] = minv;
272:     glyph->texcoords[4] = maxu;
273:     glyph->texcoords[5] = maxv;
274:     glyph->texcoords[6] = minu;
275:     glyph->texcoords[7] = maxv;
276: 
277:     return glyph;
278: }
