280: static AtlasGlyph *FindUnusedGlyph(AtlasTexture *atlas, int width, int height)
281: {
282:     AtlasGlyph *glyph, *prev = NULL;
283: 
284:     int size = (width * height);
285:     for (glyph = atlas->free_glyphs; glyph; glyph = glyph->next) {
286:         if (width == glyph->rect.w && height == glyph->rect.h) {
287:             if (prev) {
288:                 prev->next = glyph->next;
289:             } else {
290:                 atlas->free_glyphs = glyph->next;
291:             }
292:             ++glyph->refcount;
293:             return glyph;
294:         }
295: 
296:         if (size < (glyph->rect.w * glyph->rect.h)) {
297:             // We didn't find any entries our size, everything else is larger than we want
298:             break;
299:         }
300: 
301:         prev = glyph;
302:     }
303: 
304:     if (atlas->next) {
305:         return FindUnusedGlyph(atlas->next, width, height);
306:     }
307:     return NULL;
308: }
