310: static bool UpdateGlyph(AtlasGlyph *glyph, SDL_Surface *surface, TTF_ImageType image_type)
311: {
312:     SDL_Texture *texture = glyph->atlas->texture;
313:     void *pixels;
314:     int pitch;
315:     if (!SDL_LockTexture(texture, &glyph->rect, &pixels, &pitch)) {
316:         return false;
317:     }
318: 
319:     const Uint8 *src = (const Uint8 *)surface->pixels;
320:     const int src_pitch = surface->pitch;
321:     Uint8 *dst = (Uint8 *)pixels;
322:     const int dst_pitch = pitch;
323:     for (int i = 0; i < glyph->rect.h; ++i) {
324:         SDL_memcpy(dst, src, glyph->rect.w * 4);
325:         src += src_pitch;
326:         dst += dst_pitch;
327:     }
328:     SDL_UnlockTexture(texture);
329: 
330:     glyph->image_type = image_type;
331:     return true;
332: }
