342: static bool ResolveMissingGlyphs(TTF_RendererTextEngineData *enginedata, AtlasTexture *atlas, TTF_RendererTextEngineFontData *fontdata, GlyphSurface *surfaces, TTF_DrawOperation *ops, int num_ops, stbrp_rect *missing, int num_missing)
343: {
344:     // See if we can reuse any existing entries
345:     if (atlas->free_glyphs) {
346:         // Search from the smallest to the largest to minimize time spent searching the free list and shortening the missing entries
347:         for (int i = num_missing; i--; ) {
348:             AtlasGlyph *glyph = FindUnusedGlyph(atlas, missing[i].w, missing[i].h);
349:             if (!glyph) {
350:                 continue;
351:             }
352: 
353:             GlyphSurface *surface = &surfaces[missing[i].id];
354:             if (!UpdateGlyph(glyph, surface->surface, surface->image_type)) {
355:                 ReleaseGlyph(glyph);
356:                 return false;
357:             }
358: 
359:             TTF_DrawOperation *op = &ops[missing[i].id];
360:             if (!AddGlyphToFont(fontdata, op->copy.glyph_font, op->copy.glyph_index, glyph)) {
361:                 ReleaseGlyph(glyph);
362:                 return false;
363:             }
364: 
365:             op->copy.reserved = glyph;
366: 
367:             // Remove this from the missing entries
368:             --num_missing;
369:             if (i < num_missing) {
370:                 SDL_memmove(&missing[i], &missing[i + 1], (num_missing - i) * sizeof(missing[i]));
371:             }
372:         }
373:         if (num_missing == 0) {
374:             return true;
375:         }
376:     }
377: 
378:     // Try to pack all the missing glyphs into the current atlas
379:     bool all_packed = (stbrp_pack_rects(&atlas->packer, missing, num_missing) == 1);
380: 
381:     for (int i = 0; i < num_missing; ++i) {
382:         if (!missing[i].was_packed) {
383:             continue;
384:         }
385: 
386:         AtlasGlyph *glyph = CreateGlyph(atlas, enginedata->atlas_texture_size, &missing[i]);
387:         if (!glyph) {
388:             return false;
389:         }
390: 
391:         GlyphSurface *surface = &surfaces[missing[i].id];
392:         if (!UpdateGlyph(glyph, surface->surface, surface->image_type)) {
393:             ReleaseGlyph(glyph);
394:             return false;
395:         }
396: 
397:         TTF_DrawOperation *op = &ops[missing[i].id];
398:         if (!AddGlyphToFont(fontdata, op->copy.glyph_font, op->copy.glyph_index, glyph)) {
399:             ReleaseGlyph(glyph);
400:             return false;
401:         }
402: 
403:         op->copy.reserved = glyph;
404:     }
405: 
406:     if (all_packed) {
407:         return true;
408:     }
409: 
410:     // Sort the remaining missing glyphs and try in the next atlas
411:     SDL_qsort_r(missing, num_missing, sizeof(*missing), SortMissing, ops);
412:     for (int i = 0; i < num_missing; ++i) {
413:         if (ops[missing[i].id].copy.reserved) {
414:             // No longer missing!
415:             num_missing = i;
416:             break;
417:         }
418:     }
419: 
420:     if (!atlas->next) {
421:         atlas->next = CreateAtlas(enginedata->renderer, enginedata->atlas_texture_size);
422:         if (!atlas->next) {
423:             return false;
424:         }
425:     }
426:     return ResolveMissingGlyphs(enginedata, atlas->next, fontdata, surfaces, ops, num_ops, missing, num_missing);
427: }
428: 
429: static bool CreateMissingGlyphs(TTF_RendererTextEngineData *enginedata, TTF_RendererTextEngineFontData *fontdata, TTF_DrawOperation *ops, int num_ops, int num_missing)
430: {
431:     stbrp_rect *missing = NULL;
432:     GlyphSurface *surfaces = NULL;
433:     SDL_HashTable *checked = NULL;
434:     bool result = false;
435:     int atlas_texture_size = enginedata->atlas_texture_size;
436: 
437:     // Build a list of missing glyphs
438:     missing = (stbrp_rect *)SDL_calloc(num_missing, sizeof(*missing));
439:     if (!missing) {
440:         goto done;
441:     }
442: 
443:     surfaces = (GlyphSurface *)SDL_calloc(num_ops, sizeof(*surfaces));
444:     if (!surfaces) {
445:         goto done;
446:     }
447: 
448:     checked = SDL_CreateGlyphHashTable(NULL);
449:     if (!checked) {
450:         goto done;
451:     }
452: 
453:     int missing_index = 0;
454:     for (int i = 0; i < num_ops; ++i) {
455:         TTF_DrawOperation *op = &ops[i];
456:         if (op->cmd == TTF_DRAW_COMMAND_COPY && !op->copy.reserved) {
457:             TTF_Font *glyph_font = op->copy.glyph_font;
458:             Uint32 glyph_index = op->copy.glyph_index;
459:             if (SDL_FindInGlyphHashTable(checked, glyph_font, glyph_index, NULL)) {
460:                 continue;
461:             }
462:             if (!SDL_InsertIntoGlyphHashTable(checked, glyph_font, glyph_index, NULL)) {
463:                 goto done;
464:             }
465: 
466:             TTF_ImageType image_type = TTF_IMAGE_INVALID;
467:             SDL_Surface *surface = TTF_GetGlyphImageForIndex(glyph_font, glyph_index, &image_type);
468:             if (!surface) {
469:                 goto done;
470:             }
471:             if (surface->w > atlas_texture_size || surface->h > atlas_texture_size) {
472:                 SDL_SetError("Glyph surface %dx%d larger than atlas texture %dx%d",
473:                     surface->w, surface->h,
474:                     atlas_texture_size, atlas_texture_size);
475:                 goto done;
476:             }
477: 
478:             surfaces[i].surface = surface;
479:             surfaces[i].image_type = image_type;
480: 
481:             missing[missing_index].id = i;
482:             missing[missing_index].w = surface->w;
483:             missing[missing_index].h = surface->h;
484:             ++missing_index;
485:         }
486:     }
487:     num_missing = missing_index;
488: 
489:     // Sort the glyphs by size
490:     SDL_qsort_r(missing, num_missing, sizeof(*missing), SortMissing, ops);
491: 
492:     // Create the texture atlas if necessary
493:     if (!enginedata->atlas) {
494:         enginedata->atlas = CreateAtlas(enginedata->renderer, atlas_texture_size);
495:         if (!enginedata->atlas) {
496:             goto done;
497:         }
498:     }
499: 
500:     if (!ResolveMissingGlyphs(enginedata, enginedata->atlas, fontdata, surfaces, ops, num_ops, missing, num_missing)) {
501:         goto done;
502:     }
503: 
504:     // Resolve any duplicates
505:     for (int i = 0; i < num_ops; ++i) {
506:         TTF_DrawOperation *op = &ops[i];
507:         if (op->cmd == TTF_DRAW_COMMAND_COPY && !op->copy.reserved) {
508:             if (!SDL_FindInGlyphHashTable(fontdata->glyphs, op->copy.glyph_font, op->copy.glyph_index, (const void **)&op->copy.reserved)) {
509:                 // Something is very wrong...
510:                 goto done;
511:             }
512:         }
513:     }
514: 
515:     result = true;
516: 
517: done:
518:     SDL_DestroyGlyphHashTable(checked);
519:     if (surfaces) {
520:         for (int i = 0; i < num_ops; ++i) {
521:             SDL_DestroySurface(surfaces[i].surface);
522:         }
523:         SDL_free(surfaces);
524:     }
525:     SDL_free(missing);
526:     return result;
527: }
