563: static AtlasDrawSequence *CreateDrawSequence(TTF_DrawOperation *ops, int num_ops)
564: {
565:     AtlasDrawSequence *sequence = (AtlasDrawSequence *)SDL_calloc(1, sizeof(*sequence));
566:     if (!sequence) {
567:         return NULL;
568:     }
569: 
570:     SDL_Texture *texture = GetOperationTexture(&ops[0]);
571:     TTF_ImageType image_type = GetOperationImageType(&ops[0]);
572:     TTF_DrawOperation *end = NULL;
573:     for (int i = 1; i < num_ops; ++i) {
574:         if (GetOperationTexture(&ops[i]) != texture ||
575:             GetOperationImageType(&ops[i]) != image_type) {
576:             end = &ops[i];
577:             break;
578:         }
579:     }
580: 
581:     int count = (end ? (int)(end - ops) : num_ops);
582:     sequence->texture = texture;
583:     sequence->image_type = image_type;
584:     sequence->num_rects = count;
585:     sequence->rects = (SDL_Rect *)SDL_malloc(count * sizeof(*sequence->rects));
586:     if (!sequence->rects) {
587:         DestroyDrawSequence(sequence);
588:         return NULL;
589:     }
590: 
591:     for (int i = 0; i < count; ++i) {
592:         TTF_DrawOperation *op = &ops[i];
593:         SDL_Rect *dst = NULL;
594:         switch (op->cmd) {
595:         case TTF_DRAW_COMMAND_FILL:
596:             dst = &op->fill.rect;
597:             break;
598:         case TTF_DRAW_COMMAND_COPY:
599:             dst = &op->copy.dst;
600:             break;
601:         default:
602:             break;
603:         }
604:         SDL_copyp(&sequence->rects[i], dst);
605:     }
606: 
607:     if (texture) {
608:         AtlasGlyph *glyph;
609: 
610:         sequence->texcoords = (float *)SDL_malloc(count * sizeof(glyph->texcoords));
611:         if (!sequence->texcoords) {
612:             DestroyDrawSequence(sequence);
613:             return NULL;
614:         }
615: 
616:         float *texcoords = sequence->texcoords;
617:         for (int i = 0; i < count; ++i) {
618:             glyph = (AtlasGlyph *)ops[i].copy.reserved;
619:             SDL_memcpy(texcoords, glyph->texcoords, sizeof(glyph->texcoords));
620:             texcoords += SDL_arraysize(glyph->texcoords);
621:         }
622:     }
623: 
624:     sequence->positions = (float *)SDL_malloc(count * 8 * sizeof(*sequence->positions));
625:     if (!sequence->positions) {
626:         DestroyDrawSequence(sequence);
627:         return NULL;
628:     }
629: 
630:     sequence->indices = (int *)SDL_malloc(count * 12 * sizeof(*sequence->indices));
631:     if (!sequence->indices) {
632:         DestroyDrawSequence(sequence);
633:         return NULL;
634:     }
635: 
636:     static const Uint8 rect_index_order[] = { 0, 1, 2, 0, 2, 3 };
637:     int vertex_index = 0;
638:     int *indices = sequence->indices;
639:     for (int i = 0; i < count; ++i) {
640:         *indices++ = vertex_index + rect_index_order[0];
641:         *indices++ = vertex_index + rect_index_order[1];
642:         *indices++ = vertex_index + rect_index_order[2];
643:         *indices++ = vertex_index + rect_index_order[3];
644:         *indices++ = vertex_index + rect_index_order[4];
645:         *indices++ = vertex_index + rect_index_order[5];
646:         vertex_index += 4;
647:     }
648: 
649:     if (count < num_ops) {
650:         sequence->next = CreateDrawSequence(ops + count, num_ops - count);
651:         if (!sequence->next) {
652:             DestroyDrawSequence(sequence);
653:             return NULL;
654:         }
655:     }
656:     return sequence;
657: }
