674: static TTF_RendererTextEngineTextData *CreateTextData(TTF_RendererTextEngineData *enginedata, TTF_RendererTextEngineFontData *fontdata, TTF_DrawOperation *ops, int num_ops)
675: {
676:     TTF_RendererTextEngineTextData *data = (TTF_RendererTextEngineTextData *)SDL_calloc(1, sizeof(*data));
677:     if (!data) {
678:         return NULL;
679:     }
680: 
681:     // First, match draw operations to existing glyphs
682:     int num_glyphs = 0;
683:     int num_missing = 0;
684:     for (int i = 0; i < num_ops; ++i) {
685:         TTF_DrawOperation *op = &ops[i];
686: 
687:         if (op->cmd != TTF_DRAW_COMMAND_COPY) {
688:             continue;
689:         }
690: 
691:         ++num_glyphs;
692: 
693:         if (!SDL_FindInGlyphHashTable(fontdata->glyphs, op->copy.glyph_font, op->copy.glyph_index, (const void **)&op->copy.reserved)) {
694:             ++num_missing;
695:         }
696:     }
697: 
698:     // Create any missing glyphs
699:     if (num_missing > 0) {
700:         if (!CreateMissingGlyphs(enginedata, fontdata, ops, num_ops, num_missing)) {
701:             DestroyTextData(data);
702:             return NULL;
703:         }
704:     }
705: 
706:     // Add references to all the glyphs
707:     data->glyphs = (AtlasGlyph **)SDL_malloc(num_glyphs * sizeof(*data->glyphs));
708:     for (int i = 0; i < num_ops; ++i) {
