902: bool TTF_DrawRendererText(TTF_Text *text, float x, float y)
903: {
904:     if (!text || !text->internal || text->internal->engine->CreateText != CreateText) {
905:         return SDL_InvalidParamError("text");
906:     }
907: 
908:     // Make sure the text is up to date
909:     if (!TTF_UpdateText(text)) {
910:         return false;
911:     }
912: 
913:     TTF_RendererTextEngineTextData *data = (TTF_RendererTextEngineTextData *)text->internal->engine_text;
914:     if (!data) {
915:         // Empty string, nothing to do
916:         return true;
917:     }
918: 
919:     SDL_Renderer *renderer = ((TTF_RendererTextEngineData *)text->internal->engine->userdata)->renderer;
920:     AtlasDrawSequence *sequence = data->draw_sequence;
921:     while (sequence) {
922:         float *position = sequence->positions;
923:         for (int i = 0; i < sequence->num_rects; ++i) {
924:             const SDL_Rect *dst = &sequence->rects[i];
925:             float minx = x + dst->x;
926:             float maxx = x + dst->x + dst->w;
927:             float miny = y + dst->y;
928:             float maxy = y + dst->y + dst->h;
929: 
930:             *position++ = minx;
931:             *position++ = miny;
932:             *position++ = maxx;
933:             *position++ = miny;
934:             *position++ = maxx;
935:             *position++ = maxy;
936:             *position++ = minx;
937:             *position++ = maxy;
938:         }
939: 
940:         SDL_FColor color;
941:         if (sequence->image_type == TTF_IMAGE_ALPHA) {
942:             SDL_copyp(&color, &text->internal->color);
943:         } else {
944:             // Don't alter the color data in the image
945:             color.r = 1.0f;
946:             color.g = 1.0f;
947:             color.b = 1.0f;
948:             color.a = text->internal->color.a;
949:         }
950: 
951:         SDL_RenderGeometryRaw(renderer,
952:                               sequence->texture,
953:                               sequence->positions, 2 * sizeof(float),
954:                               &color, 0,
955:                               sequence->texcoords, 2 * sizeof(float),
956:                               sequence->num_rects * 4,
957:                               sequence->indices, sequence->num_rects * 6, sizeof(*sequence->indices));
958: 
959:         sequence = sequence->next;
