138:         SDL_assert(item_probe_len == get_probe_length(item_hash & hash_mask, (Uint32)(item - table), hash_mask + 1));
139: 
140:         if (*probe_len > item_probe_len) {
141:             return NULL;
142:         }
143: 
144:         if (++*probe_len > max_probe_len) {
