159: static SDL_HashItem *insert_item(SDL_HashItem *item_to_insert, SDL_HashItem *table, Uint32 hash_mask, Uint32 *max_probe_len_ptr)
160: {
161:     const Uint32 num_buckets = hash_mask + 1;
162:     Uint32 idx = item_to_insert->hash & hash_mask;
163:     SDL_HashItem *target = NULL;
164:     SDL_HashItem temp_item;
165: 
166:     while (true) {
167:         SDL_HashItem *candidate = table + idx;
168: 
169:         if (!candidate->live) {
170:             // Found an empty slot. Put it here and we're done.
171:             *candidate = *item_to_insert;
172: 
173:             if (target == NULL) {
174:                 target = candidate;
175:             }
176: 
177:             const Uint32 probe_len = get_probe_length(candidate->hash & hash_mask, idx, num_buckets);
178:             candidate->probe_len = probe_len;
179: 
180:             if (*max_probe_len_ptr < probe_len) {
181:                 *max_probe_len_ptr = probe_len;
182:             }
183: 
184:             break;
185:         }
186: 
187:         const Uint32 candidate_probe_len = candidate->probe_len;
188:         SDL_assert(candidate_probe_len == get_probe_length(candidate->hash & hash_mask, idx, num_buckets));
189:         const Uint32 new_probe_len = get_probe_length(item_to_insert->hash & hash_mask, idx, num_buckets);
190: 
191:         if (candidate_probe_len < new_probe_len) {
192:             // Robin Hood hashing: the item at idx has a better probe length than our item would at this position.
193:             // Evict it and put our item in its place, then continue looking for a new spot for the displaced item.
194:             // This algorithm significantly reduces clustering in the table, making lookups take very few probes.
195: 
196:             temp_item = *candidate;
197:             *candidate = *item_to_insert;
198: 
199:             if (target == NULL) {
200:                 target = candidate;
201:             }
202: 
203:             *item_to_insert = temp_item;
204: 
205:             SDL_assert(new_probe_len == get_probe_length(candidate->hash & hash_mask, idx, num_buckets));
206:             candidate->probe_len = new_probe_len;
207: 
208:             if (*max_probe_len_ptr < new_probe_len) {
209:                 *max_probe_len_ptr = new_probe_len;
210:             }
211:         }
212: 
213:         idx = (idx + 1) & hash_mask;
214:     }
215: 
216:     return target;
217: }
