219: static void delete_item(SDL_HashTable *ht, SDL_HashItem *item)
220: {
221:     const Uint32 hash_mask = ht->hash_mask;
222:     SDL_HashItem *table = ht->table;
223: 
224:     if (ht->destroy) {
225:         ht->destroy(ht->userdata, item->key, item->value);
226:     }
227: 
228:     SDL_assert(ht->num_occupied_slots > 0);
229:     ht->num_occupied_slots--;
230: 
231:     Uint32 idx = (Uint32)(item - ht->table);
