233:     while (true) {
234:         idx = (idx + 1) & hash_mask;
235:         SDL_HashItem *next_item = table + idx;
236: 
237:         if (next_item->probe_len < 1) {
238:             SDL_zerop(item);
239:             return;
240:         }
241: 
242:         *item = *next_item;
243:         item->probe_len -= 1;
244:         SDL_assert(item->probe_len < ht->max_probe_len);
245:         item = next_item;
