294: bool SDL_InsertIntoHashTable(SDL_HashTable *table, const void *key, const void *value, bool replace)
295: {
296:     if (!table) {
297:         return SDL_InvalidParamError("table");
298:     }
299: 
300:     bool result = false;
301: 
302:     SDL_LockRWLockForWriting(table->lock);
303: 
304:     const Uint32 hash = calc_hash(table, key);
305:     SDL_HashItem *item = find_first_item(table, key, hash);
306:     bool do_insert = true;
307: 
308:     if (item) {
309:         if (replace) {
310:             delete_item(table, item);
311:         } else {
312:             SDL_SetError("key already exists and replace is disabled");
313:             do_insert = false;
314:         }
315:     }
316: 
317:     if (do_insert) {
318:         SDL_HashItem new_item;
319:         new_item.key = key;
320:         new_item.value = value;
321:         new_item.hash = hash;
322:         new_item.live = true;
323:         new_item.probe_len = 0;
